155	/** Raised when a scoped lookup finds nothing; mapped to `not_found` by callers. */
156	export class NotFoundError extends Error {
157	  readonly code = "not_found" as const;
158	
159	  constructor(
160	    readonly entity: string,
161	    readonly id: string,
162	  ) {
163	    super(`${entity} ${id} was not found`);
164	    this.name = "NotFoundError";
165	  }
166	}
