168	/** Unwraps a repository read, turning the `null` case into a domain error. */
169	export function requireFound<T>(
170	  value: T | null | undefined,
171	  entity: string,
172	  id: string,
173	): T {
174	  if (value === null || value === undefined) {
175	    throw new NotFoundError(entity, id);
176	  }
177	  return value;
178	}
