304	/** Every org the user still holds a live membership in. */
305	export async function listOrgsForUser(
306	  userId: UserId,
307	): Promise<readonly Organization[]> {
308	  const rows = getDb()
309	    .select({ org: organizations })
310	    .from(members)
311	    .innerJoin(organizations, eq(organizations.id, members.orgId))
312	    .where(
313	      and(
314	        eq(members.userId, userId),
315	        isNull(members.archivedAt),
316	        isNull(organizations.archivedAt),
317	      ),
318	    )
319	    .all();
320	
321	  return rows.map((row) => toOrganization(row.org));
322	}
