355	export async function updateOrg(
356	  orgId: OrgId,
357	  patch: UpdateOrganizationInput,
358	): Promise<Organization> {
359	  const current = await findOrgById(orgId);
360	  if (!current) throw new Error(`Organization ${orgId} not found`);
361	
362	  const settings = { ...current.settings, ...(patch.settings ?? {}) };
363	
364	  const row = getDb()
365	    .update(organizations)
366	    .set({
367	      ...(patch.name === undefined ? {} : { name: patch.name }),
368	      ...(patch.logoUrl === undefined ? {} : { logoUrl: patch.logoUrl }),
369	      defaultIssueStatus: settings.defaultIssueStatus,
370	      allowPublicProjects: settings.allowPublicProjects,
371	      requireTwoFactor: settings.requireTwoFactor,
372	      digestHourUtc: settings.digestHourUtc,
373	      enabledFlagOverrides: JSON.stringify(settings.enabledFlagOverrides),
374	      updatedAt: toIsoTimestamp(new Date()),
375	    })
376	    .where(eq(organizations.id, orgId))
377	    .returning()
378	    .get();
379	
380	  return toOrganization(row);
