508	export async function runDigestEmailJob(now: Date): Promise<JobResult> {
509	  return runJob("digest-email", async (result) => {
510	    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);
511	
512	    for (const orgId of orgIds) {
513	      const org = await orgRepo.findOrgById(orgId);
514	      if (!org || !shouldRunForOrg(org, now)) continue;
515	
516	      if (!isEnabled("digest_email", buildFlagContext(null, org))) continue;
517	
518	      const windowEnd = toIsoTimestamp(now);
519	      const windowStart = toIsoTimestamp(new Date(now.getTime() - MS_PER_DAY));
520	
521	      for (const recipientId of await listDigestRecipients(orgId)) {
522	        try {
523	          const bundle = await buildDigest(
524	            orgId,
525	            recipientId,
526	            windowStart,
527	            windowEnd,
528	          );
529	          if (!bundle) continue;
