895	          delivery.id,
896	          `giving up after ${delivery.attempts} attempts`,
897	        );
898	        result.failed += 1;
899	        continue;
900	      }
901	
902	      const endpoint = (await webhookRepo.listEndpoints(orgId)).find(
903	        (row) => row.id === delivery.endpointId,
904	      );
905	
906	      if (!endpoint || !endpoint.enabled) {
