429	/**
430	 * The retention sweep. Soft-deleted rows are kept for as long as the plan
431	 * promises and no longer: the cut-off comes from `retentionDays`, so an
432	 * enterprise tenant keeps years of history where a free one keeps a month.
433	 *
434	 * Only the search documents are actually dropped here — the issue rows stay,
435	 * because the audit log still points at them — while the audit rows past the
436	 * window are purged outright.
437	 */
438	export async function runCleanupArchivedJob(now: Date): Promise<JobResult> {
439	  return runJob("cleanup-archived", async (result) => {
440	    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);
441	
442	    for (const orgId of orgIds) {
443	      const org = await orgRepo.findOrgById(orgId);
444	      if (!org) continue;
445	
446	      const { retentionDays } = getPlanLimits(org.plan);
447	      const cutoff = toIsoTimestamp(
448	        new Date(now.getTime() - retentionDays * MS_PER_DAY),
449	      );
450	
451	      const archived = await issueRepo.listIssues({
452	        orgId,
453	        limit: PAGE_SIZE,
454	        cursor: null,
455	        includeArchived: true,
456	      });
457	
458	      for (const issue of archived.items) {
459	        if (!isArchived(issue)) continue;
460	        if (issue.archivedAt === null || issue.archivedAt > cutoff) continue;
461	
462	        await searchRepo.deleteSearchDocument(orgId, "issue", issue.id);
463	        result.processed += 1;
464	      }
465	
466	      try {
467	        const purged = await activityRepo.purgeActivityBefore(orgId, cutoff);
468	        result.processed += purged;
469	      } catch (error) {
470	        result.failed += 1;
471	        logger.error("activity purge failed", {
472	          orgId,
473	          reason: error instanceof Error ? error.message : String(error),
474	        });
475	      }
476	    }
477	  });
478	}
