508	export async function runDigestEmailJob(now: Date): Promise<JobResult> {
509	  return runJob("digest-email", async (result) => {
510	    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);
511	
512	    for (const orgId of orgIds) {
513	      const org = await orgRepo.findOrgById(orgId);
514	      if (!org || !shouldRunForOrg(org, now)) continue;
515	
516	      if (!isEnabled("digest_email", buildFlagContext(null, org))) continue;
517	
518	      const windowEnd = toIsoTimestamp(now);
519	      const windowStart = toIsoTimestamp(new Date(now.getTime() - MS_PER_DAY));
520	
521	      for (const recipientId of await listDigestRecipients(orgId)) {
522	        try {
523	          const bundle = await buildDigest(
524	            orgId,
525	            recipientId,
526	            windowStart,
527	            windowEnd,
528	          );
529	          if (!bundle) continue;
530	
531	          const recipient = await userRepo.findUserById(recipientId);
532	          if (!recipient) continue;
533	
534	          const rendered = await renderDigest(bundle, recipient);
535	          await sendEmail({ to: recipient.email, ...rendered });
536	
537	          // Once digested, these notifications are no longer "unread" — this
538	          // is what keeps a later run inside the same window from sending
539	          // the same digest twice.
540	          for (const entry of bundle.entries) {
541	            await notificationRepo.markRead(orgId, entry.notificationId, windowEnd);
542	          }
543	
544	          result.processed += 1;
545	        } catch (error) {
546	          result.failed += 1;
547	          logger.error("digest failed", {
548	            orgId,
549	            recipientId,
550	            reason: error instanceof Error ? error.message : String(error),
551	          });
552	        }
553	      }
554	    }
555	  });
556	}
