581	  assertCan(actor, "member:invite", orgResource(input.orgId));
582	
583	  const verdict = await consumeRateLimit(
584	    input.orgId,
585	    INVITE_BUCKET,
586	    input.invites.length,
587	  );
588	  if (!verdict.allowed) {
589	    throw new Error(
590	      `Invite rate limit reached; try again after ${verdict.resetAt}`,
591	    );
592	  }
593	
594	  const org = requireFound(
595	    await orgRepo.findOrgById(input.orgId),
596	    "Organization",
597	    input.orgId,
598	  );
599	
600	  const seatsUsed =
601	    (await memberRepo.countActiveMembers(input.orgId)) +
602	    (await invitationRepo.countPendingInvitations(input.orgId));
603	
604	  if (
605	    wouldExceedLimit(org.plan, "seats", seatsUsed, input.invites.length)
606	  ) {
607	    const limits = getPlanLimits(org.plan);
608	    throw new Error(
609	      `Plan ${org.plan} includes ${limits.seats} seats and ${seatsUsed} are taken`,
610	    );
611	  }
612	
613	  const invitations: Invitation[] = [];
614	
615	  for (const invite of input.invites) {
616	    const token = randomToken(32);
617	    const invitation = await invitationRepo.insertInvitation(
618	      input.orgId,
619	      {
620	        orgId: input.orgId,
621	        email: invite.email,
622	        role: invite.role,
623	        expiresInDays: DEFAULT_EXPIRY_DAYS,
624	      },
625	      actor.userId,
626	      hashToken(token),
627	    );
628	
629	    invitations.push(invitation);
630	
631	    await emit("member.invited", {
632	      orgId: input.orgId,
633	      actorId: actor.userId,
634	      occurredAt: invitation.createdAt,
635	      email: invite.email,
636	      role: invite.role,
637	    });
638	  }
639	
640	  return invitations;
641	}
