643	/**
644	 * Accepting runs unauthenticated: the token is the credential, so there is no
645	 * `Actor` to scope against and every check has to come off the stored row.
646	 */
647	export async function acceptInvitation(
648	  userId: UserId,
649	  input: AcceptInvitationTokenInput,
650	): Promise<Member> {
651	  const invitation = requireFound(
652	    await invitationRepo.findInvitationByTokenHash(hashToken(input.token)),
653	    "Invitation",
