657	  if (invitation.revokedAt !== null) {
658	    throw new Error("That invitation has been revoked");
659	  }
660	  if (invitation.acceptedAt !== null) {
661	    throw new Error("That invitation has already been accepted");
662	  }
663	  if (invitation.expiresAt <= toIsoTimestamp(new Date())) {
664	    throw new Error("That invitation has expired");
