728	/**
729	 * The fan-out hub: one domain event becomes in-app rows, an email draft and/or a digest entry, filtered by each recipient's preferences.
730	 *
731	 * Must call (do not reimplement): assertCan, assertOrgScope, isEnabled, subscribe
732	 */
733	import { subscribe } from "@/lib/event-bus";
734	import { isEnabled } from "@/lib/feature-flags";
735	import { assertCan } from "@/lib/permissions";
736	import { assertOrgScope } from "@/lib/tenant";
737	import * as issueRepo from "@/server/repositories/issue-repository";
738	import * as notificationRepo from "@/server/repositories/notification-repository";
739	import * as orgRepo from "@/server/repositories/organization-repository";
740	import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
741	import { toIsoTimestamp } from "@/types/common";
742	import { notificationResource, requireFound } from "./_support";
743	import type {
744	  ListNotificationsInput,
745	  MarkNotificationReadInput,
746	  UpdateNotificationPreferenceInput,
747	} from "@/schemas/notification";
748	import type { OrgId, Page, UserId } from "@/types/common";
749	import type { FlagContext } from "@/types/feature-flag";
750	import type { Actor } from "@/types/member";
751	import type {
752	  Notification,
753	  NotificationChannel,
754	  NotificationKind,
755	  NotificationPreference,
756	} from "@/types/notification";
757	
758	export type NotificationPayload = {
759	  title: string;
760	  body: string;
761	  href: string;
762	  actorId: UserId | null;
763	};
764	
765	/** Channels used when a recipient has never touched their preferences. */
766	const DEFAULT_CHANNELS: readonly NotificationChannel[] = ["in_app", "email"];
767	
768	/**
769	 * Writes one notification row per recipient, each with the channel set that
770	 * recipient's preferences allow. A recipient who has muted every channel is
771	 * skipped entirely rather than given a row nobody will ever see.
772	 */
773	export async function notify(
774	  orgId: OrgId,
775	  kind: NotificationKind,
776	  recipients: readonly UserId[],
777	  payload: NotificationPayload,
778	): Promise<readonly Notification[]> {
779	  if (recipients.length === 0) return [];
780	
781	  const org = await orgRepo.findOrgById(orgId);
782	  const flags: FlagContext = {
783	    orgId,
784	    userId: payload.actorId,
785	    plan: org?.plan ?? "free",
786	    role: null,
787	    overrides: org?.settings.enabledFlagOverrides,
788	  };
789	
790	  const rows = [];
791	
792	  for (const recipientId of new Set(recipients)) {
793	    if (recipientId === payload.actorId) continue;
794	
795	    const preference = await preferenceRepo.getPreference(
796	      orgId,
797	      recipientId,
798	      kind,
799	    );
800	    const channels = resolveChannels(preference, flags);
801	    if (channels.length === 0) continue;
802	
803	    rows.push({
804	      orgId,
805	      recipientId,
806	      kind,
807	      title: payload.title,
808	      body: payload.body,
809	      href: payload.href,
810	      actorId: payload.actorId,
811	      channels,
812	    });
813	  }
814	
815	  return notificationRepo.insertNotifications(orgId, rows);
816	}
