878	/**
879	 * Turns a stored preference into the channels one notification will use.
880	 * `digestOnly` suppresses the immediate email but keeps the in-app row, and
881	 * the email channel additionally requires the org's `digest_email` plan flag.
882	 */
883	export function resolveChannels(
884	  preference: NotificationPreference | null,
885	  flags: FlagContext,
886	): readonly NotificationChannel[] {
887	  if (preference === null) return DEFAULT_CHANNELS;
888	
889	  const channels: NotificationChannel[] = [];
890	  if (preference.inApp) channels.push("in_app");
891	
892	  const emailAllowed =
893	    preference.email &&
894	    (!preference.digestOnly || isEnabled("digest_email", flags));
895	
896	  if (emailAllowed) channels.push("email");
897	  return channels;
898	}
899	
900	/**
901	 * The bus wiring. Attached at module load rather than from `event-registry`
902	 * because the fan-out has no other public entry point — importing this module
903	 * is what makes an org start receiving notifications.
904	 */
905	let registered = false;
906	
907	function registerFanOut(): void {
908	  if (registered) return;
909	  registered = true;
910	
911	  subscribe("issue.assigned", async (payload) => {
912	    await notify(payload.orgId, "issue_assigned", [payload.assigneeId], {
913	      title: "You were assigned an issue",
914	      body: `Issue ${payload.issueId} is now yours`,
915	      href: `/issues/${payload.issueId}`,
916	      actorId: payload.actorId,
917	    });
918	  });
919	
920	  subscribe("issue.overdue", async (payload) => {
921	    if (payload.assigneeId === null) return;
922	    await notify(payload.orgId, "issue_overdue", [payload.assigneeId], {
923	      title: "An issue is overdue",
924	      body: `Issue ${payload.issueId} was due ${payload.dueAt}`,
925	      href: `/issues/${payload.issueId}`,
926	      actorId: null,
927	    });
928	  });
929	
930	  subscribe("comment.created", async (payload) => {
931	    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
932	    const watchers = issue
933	      ? [issue.authorId, ...(issue.assigneeId ? [issue.assigneeId] : [])]
934	      : [];
935	
936	    await notify(payload.orgId, "comment_created", watchers, {
937	      title: "New comment",
938	      body: `A comment was added to issue ${payload.issueId}`,
939	      href: `/issues/${payload.issueId}`,
940	      actorId: payload.actorId,
941	    });
942	
943	    if (payload.mentionedUserIds.length > 0) {
944	      await notify(
945	        payload.orgId,
946	        "comment_mention",
947	        payload.mentionedUserIds,
948	        {
949	          title: "You were mentioned",
950	          body: `You were mentioned on issue ${payload.issueId}`,
951	          href: `/issues/${payload.issueId}`,
952	          actorId: payload.actorId,
953	        },
954	      );
955	    }
956	  });
957	
958	  subscribe("member.joined", async (payload) => {
959	    const org = requireFound(
960	      await orgRepo.findOrgById(payload.orgId),
961	      "Organization",
962	      payload.orgId,
963	    );
964	    await notify(payload.orgId, "member_joined", [org.ownerId], {
965	      title: "A new member joined",
966	      body: `${payload.userId} joined as ${payload.role}`,
967	      href: "/settings/members",
968	      actorId: payload.userId,
969	    });
970	  });
971	}
972	
973	registerFanOut();
974	/**
975	 * Recomputes the usage counters that every `LimitCheck` compares against.
976	 *
977	 * Must call (do not reimplement): assertOrgScope, subscribe, getPlanLimits
978	 */
979	import { getPlanLimits } from "@/config/plan-limits";
980	import { emit, subscribe } from "@/lib/event-bus";
981	import { assertOrgScope } from "@/lib/tenant";
982	import * as orgRepo from "@/server/repositories/organization-repository";
983	import * as usageRepo from "@/server/repositories/usage-repository";
984	import { toIsoTimestamp } from "@/types/common";
985	import type { OrgId } from "@/types/common";
986	import type { Unsubscribe } from "@/types/event";
987	import type { Actor } from "@/types/member";
988	import type { OrganizationUsage } from "@/types/organization";
989	
990	/** Fraction of a quota at which the "approaching limit" event fires. */
991	const WARN_THRESHOLD = 0.9;
992	
993	export async function getUsage(
994	  actor: Actor,
995	  orgId: OrgId,
996	): Promise<OrganizationUsage> {
997	  assertOrgScope(actor, orgId);
998	  return usageRepo.getUsage(orgId);
999	}
1000	
1001	/**
1002	 * Full recount from the source tables. Called by the rollup job and by every
1003	 * event that could have moved a counter — after recounting, the seat and
1004	 * project totals are checked against the plan so a breach surfaces as an
1005	 * event rather than waiting for the next write to be rejected.
1006	 */
1007	export async function recomputeUsage(
1008	  orgId: OrgId,
1009	): Promise<OrganizationUsage> {
1010	  const usage = await usageRepo.recomputeUsage(orgId);
1011	  const org = await orgRepo.findOrgById(orgId);
1012	  if (!org) return usage;
1013	
1014	  const limits = getPlanLimits(org.plan);
1015	
1016	  if (usage.seatsUsed >= limits.seats * WARN_THRESHOLD) {
1017	    await emit("billing.limit_exceeded", {
1018	      orgId,
1019	      actorId: null,
1020	      occurredAt: toIsoTimestamp(new Date()),
1021	      resource: "seats",
1022	      limit: limits.seats,
1023	      used: usage.seatsUsed,
1024	    });
1025	  }
1026	
1027	  if (usage.projectsUsed >= limits.projects * WARN_THRESHOLD) {
1028	    await emit("billing.limit_exceeded", {
1029	      orgId,
1030	      actorId: null,
1031	      occurredAt: toIsoTimestamp(new Date()),
1032	      resource: "projects",
1033	      limit: limits.projects,
1034	      used: usage.projectsUsed,
1035	    });
1036	  }
1037	
1038	  return usage;
1039	}
1040	
1041	/**
1042	 * Every event that changes a counted resource nudges the cache. The deltas are
1043	 * cheap; the periodic rollup is what corrects any drift they accumulate.
1044	 */
1045	export function registerUsageListeners(): Unsubscribe {
1046	  const offs: Unsubscribe[] = [
1047	    subscribe("issue.created", async (payload) => {
1048	      await usageRepo.incrementUsage(payload.orgId, { issuesUsed: 1 });
1049	    }),
1050	    subscribe("issue.archived", async (payload) => {
1051	      await usageRepo.incrementUsage(payload.orgId, { issuesUsed: -1 });
1052	    }),
1053	    subscribe("project.created", async (payload) => {
1054	      await usageRepo.incrementUsage(payload.orgId, { projectsUsed: 1 });
1055	    }),
1056	    subscribe("project.archived", async (payload) => {
1057	      await usageRepo.incrementUsage(payload.orgId, {
1058	        projectsUsed: -1,
1059	        issuesUsed: -payload.issuesArchived,
1060	      });
1061	    }),
1062	    subscribe("member.joined", async (payload) => {
1063	      await usageRepo.incrementUsage(payload.orgId, { seatsUsed: 1 });
1064	    }),
1065	    subscribe("member.removed", async (payload) => {
1066	      await usageRepo.incrementUsage(payload.orgId, { seatsUsed: -1 });
1067	    }),
1068	  ];
1069	
1070	  return () => {
1071	    for (const off of offs) off();
1072	  };
1073	}
