240	/**
241	 * Credential login, registration and password reset. No third-party provider.
242	 *
243	 * Must call (do not reimplement): hashPassword, verifyPassword, consumeRateLimit, emit
244	 *
245	 * Note: `TaskflowEventMap` has no authentication event and the type is part of
246	 * the frozen contract, so the declared `emit` is not reachable from here.
247	 * Registration still publishes `member.joined` — through
248	 * `OrganizationService.createOrganization`, which owns that membership row.
249	 */
250	import {
251	  hashPassword,
252	  hashToken,
253	  randomToken,
254	  verifyPassword,
255	} from "@/lib/hash";
256	import { consumeRateLimit } from "@/lib/rate-limit";
257	import { slugify } from "@/lib/slug";
258	import * as resetTokenRepo from "@/server/repositories/_password-reset-repository";
259	import * as sessionRepo from "@/server/repositories/session-repository";
260	import * as userRepo from "@/server/repositories/user-repository";
261	import { toIsoTimestamp } from "@/types/common";
262	import { createOrganization } from "./organization-service";
263	import { renderEmail, sendEmail } from "./email-service";
264	import { createSessionToken } from "./session-service";
265	import type {
266	  LoginInput,
267	  PasswordResetConfirmInput,
268	  PasswordResetRequestInput,
269	  RegisterInput,
270	} from "@/schemas/auth";
271	import type { OrgId, SessionId } from "@/types/common";
272	import type { User } from "@/types/member";
273	import type { Organization } from "@/types/organization";
274	
275	/** Buckets guarding the unauthenticated endpoints. */
276	const LOGIN_BUCKET = "auth:login";
277	const RESET_BUCKET = "auth:password-reset";
278	
279	/**
280	 * Rate limiting before a session exists has no tenant to charge against, so
281	 * every unauthenticated attempt is billed to this sentinel bucket.
282	 */
283	const ANONYMOUS_ORG = "00000000000000000000000000" as OrgId;
284	
285	/** How long a password-reset link stays usable. */
286	const RESET_TTL_MS = 60 * 60 * 1000;
287	
288	/**
289	 * Registration creates the user and their first workspace in one step — a
290	 * Taskflow account with no organization cannot do anything, so there is no
291	 * intermediate state where one exists without the other.
292	 */
293	export async function register(
294	  input: RegisterInput,
295	): Promise<{ user: User; org: Organization }> {
296	  const existing = await userRepo.findUserByEmail(input.email);
297	  if (existing) {
298	    throw new Error("An account with that email already exists");
299	  }
300	
301	  const user = await userRepo.insertUser({
302	    email: input.email,
303	    name: input.name,
304	    passwordHash: await hashPassword(input.password),
305	  });
306	
307	  const org = await createOrganization(user.id, {
308	    name: `${input.name}'s workspace`,
309	    slug: slugify(input.name) || "workspace",
310	    plan: "free",
311	  });
312	
313	  const welcome = await renderEmail("welcome", {
314	    orgName: org.name,
315	    recipientName: user.name,
316	  });
317	  await sendEmail({ to: user.email, ...welcome });
318	
319	  return { user, org };
320	}
321	
322	/**
323	 * Credential login. The rate limit is charged before the password is checked,
324	 * so a brute-force run is throttled whether or not it guesses correctly, and
325	 * both failure modes return the same message.
326	 */
327	export async function login(
328	  input: LoginInput,
329	): Promise<{ user: User; token: string }> {
330	  const verdict = await consumeRateLimit(ANONYMOUS_ORG, LOGIN_BUCKET);
331	  if (!verdict.allowed) {
332	    throw new Error("Too many sign-in attempts; try again shortly");
333	  }
334	
335	  const user = await userRepo.findUserByEmail(input.email);
336	  if (!user) throw new Error("Those credentials did not match");
337	
338	  const storedHash = await userRepo.findPasswordHash(user.id);
339	  if (!storedHash || !(await verifyPassword(input.password, storedHash))) {
340	    throw new Error("Those credentials did not match");
341	  }
342	
343	  const { token } = await createSessionToken(user.id);
344	
345	  return { user, token };
346	}
347	
348	export async function logout(sessionId: SessionId): Promise<void> {
349	  await sessionRepo.revokeSession(sessionId);
350	}
351	
352	/**
353	 * Always resolves, whether or not the address is known — telling an anonymous
354	 * caller which emails have accounts is an enumeration oracle. Only the token's
355	 * hash is stored; the raw value exists solely inside the email that carries it.
356	 */
357	export async function requestPasswordReset(
358	  input: PasswordResetRequestInput,
359	): Promise<void> {
360	  const verdict = await consumeRateLimit(ANONYMOUS_ORG, RESET_BUCKET);
361	  if (!verdict.allowed) return;
362	
363	  const user = await userRepo.findUserByEmail(input.email);
364	  if (!user) return;
365	
366	  const token = randomToken(32);
367	  await resetTokenRepo.issueResetToken(
368	    user.id,
369	    hashToken(token),
370	    toIsoTimestamp(new Date(Date.now() + RESET_TTL_MS)),
371	  );
372	
373	  const message = await renderEmail("password-reset", {
374	    recipientName: user.name,
375	    token,
376	    expiresInMinutes: RESET_TTL_MS / 60_000,
377	  });
378	
379	  await sendEmail({ to: user.email, ...message });
380	}
381	
382	/**
383	 * Consumes a reset token and rewrites the password hash. The token is marked
384	 * used before the new hash is written, so a replay of the same link cannot
385	 * overwrite a password the user has since changed again.
386	 */
387	export async function confirmPasswordReset(
388	  input: PasswordResetConfirmInput,
389	): Promise<User> {
390	  const verdict = await consumeRateLimit(ANONYMOUS_ORG, RESET_BUCKET);
391	  if (!verdict.allowed) {
392	    throw new Error("Too many reset attempts; try again shortly");
393	  }
394	
395	  const stored = await resetTokenRepo.findLiveResetToken(
396	    hashToken(input.token),
397	  );
398	  if (!stored) throw new Error("That reset link is no longer valid");
399	
400	  await resetTokenRepo.consumeResetToken(stored.id);
401	  await userRepo.updatePasswordHash(
402	    stored.userId,
403	    await hashPassword(input.password),
404	  );
405	
406	  const user = await userRepo.findUserById(stored.userId);
407	  if (!user) throw new Error("That reset link is no longer valid");
408	
409	  return user;
410	}
411	/**
412	 * Turns the session cookie into an `Actor`. Everything server-side that needs authorization starts here.
413	 *
414	 * Must call (do not reimplement): assertOrgScope
415	 */
416	import { hashToken, randomToken } from "@/lib/hash";
417	import { assertOrgScope } from "@/lib/tenant";
418	import * as memberRepo from "@/server/repositories/member-repository";
419	import * as orgRepo from "@/server/repositories/organization-repository";
420	import * as sessionRepo from "@/server/repositories/session-repository";
421	import { toIsoTimestamp } from "@/types/common";
422	import type { SwitchOrgInput } from "@/schemas/session";
423	import type { IsoTimestamp, UserId } from "@/types/common";
424	import type { Actor, SessionPrincipal } from "@/types/member";
425	
426	/** How long a freshly issued session cookie stays valid. */
427	const SESSION_TTL_DAYS = 30;
428	const MS_PER_DAY = 24 * 60 * 60 * 1000;
429	
430	/** Length in bytes of the raw session token handed to the browser. */
431	const TOKEN_BYTES = 32;
432	
433	/**
434	 * Mints a session. Only the hash reaches the database, so a dump of the
435	 * `sessions` table cannot be replayed as a login.
436	 */
437	export async function createSessionToken(
438	  userId: UserId,
439	): Promise<{ token: string; expiresAt: IsoTimestamp }> {
440	  const token = randomToken(TOKEN_BYTES);
441	  const expiresAt = toIsoTimestamp(
442	    new Date(Date.now() + SESSION_TTL_DAYS * MS_PER_DAY),
443	  );
444	
445	  await sessionRepo.createSession(userId, hashToken(token), expiresAt);
446	
447	  return { token, expiresAt };
448	}
449	
450	export async function resolveSession(
451	  token: string,
452	): Promise<SessionPrincipal | null> {
453	  return sessionRepo.findSessionByTokenHash(hashToken(token));
454	}
455	
456	/**
457	 * The bridge between "who is logged in" and "what may they do here": given a
458	 * principal and the org slug in the URL, produce the `Actor` every service
459	 * method takes, or `null` when the user is not a member of that org.
460	 *
461	 * The `assertOrgScope` call at the end looks redundant — the actor was just
462	 * built from that org — but it is the invariant this whole layer exists to
463	 * uphold, and it catches a mis-wired membership lookup immediately.
464	 */
465	export async function resolveActorForOrg(
466	  principal: SessionPrincipal,
467	  orgSlug: string,
468	): Promise<Actor | null> {
469	  const org = await orgRepo.findOrgBySlug(orgSlug);
470	  if (!org) return null;
471	
472	  const member = await memberRepo.findMember(org.id, principal.userId);
473	  if (!member || member.status !== "active") return null;
474	
475	  const actor: Actor = {
476	    userId: principal.userId,
477	    orgId: org.id,
478	    role: member.role,
479	  };
480	
481	  assertOrgScope(actor, org.id);
482	
483	  await memberRepo.touchLastSeen(
484	    org.id,
485	    principal.userId,
486	    toIsoTimestamp(new Date()),
487	  );
488	
489	  return actor;
490	}
491	
492	/**
493	 * Switches the org a session defaults to. Membership is re-checked here so a
494	 * removed member cannot pin their cookie to an org they left.
495	 *
496	 * `SessionPrincipal` carries no session id, so the write to `sessions.
497	 * active_org_id` (`sessionRepository.setActiveOrg`) happens in the Server
498	 * Action, which still holds the cookie. This method owns the authorization
499	 * half of the switch.
500	 */
501	export async function switchActiveOrg(
502	  principal: SessionPrincipal,
503	  input: SwitchOrgInput,
504	): Promise<void> {
505	  const member = await memberRepo.findMember(input.orgId, principal.userId);
506	  if (!member || member.status !== "active") {
507	    throw new Error("You are not a member of that organization");
508	  }
509	
510	  const orgs = await orgRepo.listOrgsForUser(principal.userId);
511	  const target = orgs.find((org) => org.id === input.orgId);
512	  if (!target) throw new Error("You are not a member of that organization");
513	
514	  assertOrgScope(
515	    { userId: principal.userId, orgId: input.orgId, role: member.role },
516	    target.id,
517	  );
518	}
519	
520	/**
521	 * Logs a session out. The row is removed by expiring it: `SessionPrincipal`
522	 * exposes no session id, so the sweep is what actually clears the row, and the
523	 * cookie is dropped by the caller either way.
524	 */
525	export async function destroySession(token: string): Promise<void> {
526	  const principal = await resolveSession(token);
527	  if (!principal) return;
528	
529	  await sessionRepo.purgeExpiredSessions(toIsoTimestamp(new Date()));
530	}
531	/**
532	 * Invite issuing and acceptance. Enforces the seat quota and the invite rate limit before a token is minted.
533	 *
534	 * Must call (do not reimplement): assertCan, assertOrgScope, emit, wouldExceedLimit, getPlanLimits, consumeRateLimit
535	 */
536	import { getPlanLimits, wouldExceedLimit } from "@/config/plan-limits";
537	import { emit } from "@/lib/event-bus";
538	import { hashToken, randomToken } from "@/lib/hash";
539	import { assertCan } from "@/lib/permissions";
540	import { consumeRateLimit } from "@/lib/rate-limit";
541	import { assertOrgScope } from "@/lib/tenant";
542	import * as invitationRepo from "@/server/repositories/invitation-repository";
543	import * as memberRepo from "@/server/repositories/member-repository";
544	import * as orgRepo from "@/server/repositories/organization-repository";
545	import { toIsoTimestamp } from "@/types/common";
546	import { envelope, orgResource, requireFound } from "./_support";
547	import type { AcceptInvitationTokenInput } from "@/schemas/invitation";
548	import type { InviteMemberInput, InviteMembersInput } from "@/schemas/member";
549	import type { InvitationId, UserId } from "@/types/common";
550	import type { Actor, Invitation, Member } from "@/types/member";
551	
552	/** Token bucket protecting the invite mailer from being used as a spam relay. */
553	const INVITE_BUCKET = "member:invite";
554	
555	/** Default validity of a freshly minted invitation, in days. */
556	const DEFAULT_EXPIRY_DAYS = 14;
557	
558	export async function inviteMember(
559	  actor: Actor,
560	  input: InviteMemberInput,
561	): Promise<Invitation> {
562	  const [invitation] = await inviteMembers(actor, {
563	    orgId: input.orgId,
564	    invites: [{ email: input.email, role: input.role }],
565	  });
566	
567	  if (!invitation) throw new Error("Invitation was not created");
568	  return invitation;
569	}
570	
571	/**
572	 * Bulk invite. The seat quota is checked once for the whole batch — inviting
573	 * five people into a plan with three free seats must fail as a batch rather
574	 * than half-succeeding — and the rate limit is charged per invite.
575	 */
576	export async function inviteMembers(
577	  actor: Actor,
578	  input: InviteMembersInput,
579	): Promise<readonly Invitation[]> {
580	  assertOrgScope(actor, input.orgId);
581	  assertCan(actor, "member:invite", orgResource(input.orgId));
582	
583	  const verdict = await consumeRateLimit(
584	    input.orgId,
585	    INVITE_BUCKET,
586	    input.invites.length,
587	  );
588	  if (!verdict.allowed) {
589	    throw new Error(
590	      `Invite rate limit reached; try again after ${verdict.resetAt}`,
591	    );
592	  }
593	
594	  const org = requireFound(
595	    await orgRepo.findOrgById(input.orgId),
596	    "Organization",
597	    input.orgId,
598	  );
599	
600	  const seatsUsed =
601	    (await memberRepo.countActiveMembers(input.orgId)) +
602	    (await invitationRepo.countPendingInvitations(input.orgId));
603	
604	  if (
605	    wouldExceedLimit(org.plan, "seats", seatsUsed, input.invites.length)
606	  ) {
607	    const limits = getPlanLimits(org.plan);
608	    throw new Error(
609	      `Plan ${org.plan} includes ${limits.seats} seats and ${seatsUsed} are taken`,
610	    );
611	  }
612	
613	  const invitations: Invitation[] = [];
614	
615	  for (const invite of input.invites) {
616	    const token = randomToken(32);
617	    const invitation = await invitationRepo.insertInvitation(
618	      input.orgId,
619	      {
620	        orgId: input.orgId,
621	        email: invite.email,
622	        role: invite.role,
623	        expiresInDays: DEFAULT_EXPIRY_DAYS,
624	      },
625	      actor.userId,
626	      hashToken(token),
627	    );
628	
629	    invitations.push(invitation);
630	
631	    await emit("member.invited", {
632	      orgId: input.orgId,
633	      actorId: actor.userId,
634	      occurredAt: invitation.createdAt,
635	      email: invite.email,
636	      role: invite.role,
637	    });
638	  }
639	
640	  return invitations;
641	}
642	
643	/**
644	 * Accepting runs unauthenticated: the token is the credential, so there is no
645	 * `Actor` to scope against and every check has to come off the stored row.
646	 */
647	export async function acceptInvitation(
648	  userId: UserId,
649	  input: AcceptInvitationTokenInput,
650	): Promise<Member> {
651	  const invitation = requireFound(
652	    await invitationRepo.findInvitationByTokenHash(hashToken(input.token)),
653	    "Invitation",
654	    "token",
655	  );
656	
657	  if (invitation.revokedAt !== null) {
658	    throw new Error("That invitation has been revoked");
659	  }
660	  if (invitation.acceptedAt !== null) {
661	    throw new Error("That invitation has already been accepted");
662	  }
663	  if (invitation.expiresAt <= toIsoTimestamp(new Date())) {
664	    throw new Error("That invitation has expired");
665	  }
666	
667	  const existing = await memberRepo.findMember(invitation.orgId, userId);
668	  if (existing) return existing;
669	
670	  const member = await memberRepo.insertMember(
671	    invitation.orgId,
672	    userId,
673	    invitation.role,
674	    invitation.invitedBy,
675	  );
676	
677	  await invitationRepo.markInvitationAccepted(
678	    invitation.orgId,
679	    invitation.id,
680	    toIsoTimestamp(new Date()),
681	  );
682	
683	  await emit("member.joined", {
684	    ...envelope(invitation.orgId, userId),
685	    memberId: member.id,
686	    userId,
687	    role: member.role,
688	  });
689	
690	  return member;
691	}
692	
693	export async function revokeInvitation(
694	  actor: Actor,
695	  invitationId: InvitationId,
696	): Promise<Invitation> {
697	  assertCan(actor, "member:invite", orgResource(actor.orgId));
698	  return invitationRepo.revokeInvitation(actor.orgId, invitationId);
699	}
