770	 * recipient's preferences allow. A recipient who has muted every channel is
771	 * skipped entirely rather than given a row nobody will ever see.
772	 */
773	export async function notify(
774	  orgId: OrgId,
775	  kind: NotificationKind,
776	  recipients: readonly UserId[],
777	  payload: NotificationPayload,
778	): Promise<readonly Notification[]> {
779	  if (recipients.length === 0) return [];
780	
781	  const org = await orgRepo.findOrgById(orgId);
782	  const flags: FlagContext = {
783	    orgId,
784	    userId: payload.actorId,
785	    plan: org?.plan ?? "free",
786	    role: null,
787	    overrides: org?.settings.enabledFlagOverrides,
788	  };
789	
790	  const rows = [];
791	
792	  for (const recipientId of new Set(recipients)) {
793	    if (recipientId === payload.actorId) continue;
794	
795	    const preference = await preferenceRepo.getPreference(
796	      orgId,
797	      recipientId,
798	      kind,
799	    );
800	    const channels = resolveChannels(preference, flags);
801	    if (channels.length === 0) continue;
802	
803	    rows.push({
804	      orgId,
805	      recipientId,
806	      kind,
807	      title: payload.title,
808	      body: payload.body,
809	      href: payload.href,
810	      actorId: payload.actorId,
811	      channels,
812	    });
813	  }
814	
815	  return notificationRepo.insertNotifications(orgId, rows);
816	}
