1001	/**
1002	 * Full recount from the source tables. Called by the rollup job and by every
1003	 * event that could have moved a counter — after recounting, the seat and
1004	 * project totals are checked against the plan so a breach surfaces as an
1005	 * event rather than waiting for the next write to be rejected.
1006	 */
1007	export async function recomputeUsage(
1008	  orgId: OrgId,
1009	): Promise<OrganizationUsage> {
1010	  const usage = await usageRepo.recomputeUsage(orgId);
1011	  const org = await orgRepo.findOrgById(orgId);
1012	  if (!org) return usage;
1013	
1014	  const limits = getPlanLimits(org.plan);
1015	
1016	  if (usage.seatsUsed >= limits.seats * WARN_THRESHOLD) {
1017	    await emit("billing.limit_exceeded", {
1018	      orgId,
1019	      actorId: null,
1020	      occurredAt: toIsoTimestamp(new Date()),
1021	      resource: "seats",
1022	      limit: limits.seats,
1023	      used: usage.seatsUsed,
1024	    });
1025	  }
1026	
1027	  if (usage.projectsUsed >= limits.projects * WARN_THRESHOLD) {
1028	    await emit("billing.limit_exceeded", {
1029	      orgId,
1030	      actorId: null,
1031	      occurredAt: toIsoTimestamp(new Date()),
1032	      resource: "projects",
1033	      limit: limits.projects,
1034	      used: usage.projectsUsed,
1035	    });
1036	  }
1037	
1038	  return usage;
1039	}
