1041	/**
1042	 * Every event that changes a counted resource nudges the cache. The deltas are
1043	 * cheap; the periodic rollup is what corrects any drift they accumulate.
1044	 */
1045	export function registerUsageListeners(): Unsubscribe {
1046	  const offs: Unsubscribe[] = [
1047	    subscribe("issue.created", async (payload) => {
1048	      await usageRepo.incrementUsage(payload.orgId, { issuesUsed: 1 });
1049	    }),
1050	    subscribe("issue.archived", async (payload) => {
1051	      await usageRepo.incrementUsage(payload.orgId, { issuesUsed: -1 });
1052	    }),
1053	    subscribe("project.created", async (payload) => {
1054	      await usageRepo.incrementUsage(payload.orgId, { projectsUsed: 1 });
1055	    }),
1056	    subscribe("project.archived", async (payload) => {
1057	      await usageRepo.incrementUsage(payload.orgId, {
1058	        projectsUsed: -1,
1059	        issuesUsed: -payload.issuesArchived,
1060	      });
1061	    }),
1062	    subscribe("member.joined", async (payload) => {
1063	      await usageRepo.incrementUsage(payload.orgId, { seatsUsed: 1 });
1064	    }),
1065	    subscribe("member.removed", async (payload) => {
1066	      await usageRepo.incrementUsage(payload.orgId, { seatsUsed: -1 });
1067	    }),
1068	  ];
1069	
1070	  return () => {
1071	    for (const off of offs) off();
1072	  };
1073	}
