/**
 * True once a deleted org has outlived its grace period. From that instant it
 * is gone for every caller, whether or not the retention sweep has physically
 * purged it yet — the sweep applies the same rule to decide what to remove.
 */
export function isPastDeletionWindow(org: Organization, now: Date): boolean {
  if (org.archivedAt === null) return false;
  const deletedAt = Date.parse(org.archivedAt);
  return (
    now.getTime() - deletedAt >= DELETED_WORKSPACE_RETENTION_DAYS * MS_PER_DAY
  );
}

/**
 * Deletion is a soft delete guarded by a typed confirmation, the same shape
 * GitHub uses: the caller has to retype the slug. The org is then kept, inert,
 * for `DELETED_WORKSPACE_RETENTION_DAYS` — its owner can `restoreOrganization`
 * it until the retention sweep purges it.
 */''')
