/**
 * Brings a deleted org back inside its grace period. Takes a bare `userId`:
 * no `Actor` can be resolved for a deleted workspace, so the membership is
 * looked up here and the `org:restore` check runs against it.
 *
 * Not being a member and the window having closed are both reported as
 * `NotFoundError` — to those callers the workspace does not exist.
 */
export async function restoreOrganization(
  userId: UserId,
  orgId: OrgId,
): Promise<Organization> {
  const org = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );

  const member = await memberRepo.findMember(orgId, userId);
  if (!member || member.status !== "active") {
    throw new NotFoundError("Organization", orgId);
  }

  if (isPastDeletionWindow(org, new Date())) {
    throw new NotFoundError("Organization", orgId);
  }

  const actor: Actor = { userId, orgId, role: member.role };
  assertOrgScope(actor, org.id);
  assertCan(actor, "org:restore", orgResource(org.id));

  if (!isArchived(org)) return org;

  const restored = await orgRepo.restoreOrg(orgId);

  const payload = { ...envelope(orgId, userId), slug: restored.slug };
  await emit("organization.restored", payload);
  await recordOrganizationLifecycle("organization.restored", payload);

  return restored;
}
''')

