sub(p, '''export async function listActivity(
  actor: Actor,''', '''/**
 * Payloads already written by `recordOrganizationLifecycle`. The bus hands
 * every subscriber the same payload object the publisher holds, so identity
 * is enough to tell "this event" from "another event that looks the same".
 */
const auditedLifecycleEvents = new WeakSet<object>();

/**
 * Audits a workspace deletion or restoration exactly once per event. Both the
 * bus listener and `OrganizationService` call it with the same payload: the
 * audit trail of a deletion must not depend on whether the listeners happen
 * to be wired in the current process, and must not double up when they are.
 */
export async function recordOrganizationLifecycle(
  action: "organization.deleted" | "organization.restored",
  payload: TaskflowEventMap[typeof action],
): Promise<void> {
  if (auditedLifecycleEvents.has(payload)) return;
  auditedLifecycleEvents.add(payload);

  await record(payload.orgId, action, {
    actorId: payload.actorId,
    subjectKind: "organization",
    subjectId: payload.orgId,
    projectId: null,
    summary:
      action === "organization.deleted"
        ? `Deleted organization ${payload.slug}`
        : `Restored organization ${payload.slug}`,
    metadata: { slug: payload.slug },
  });
}

