import { resolveActorForOrg } from "@/server/services/session-service";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { OrgId, UserId } from "@/types/common";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";

const MS_PER_DAY = 24 * 60 * 60 * 1000;
const WINDOW_MS = DELETED_WORKSPACE_RETENTION_DAYS * MS_PER_DAY;

let cleanup: () => void;
const detachers: Unsubscribe[] = [];
let counter = 0;

function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(subscribe(type, (payload) => void seen.push(payload)));
  return seen;
}

async function deletedTenant(): Promise<Tenant> {
  const tenant = await createTenant(`lifecycle-${++counter}`);
  await usageRepo.recomputeUsage(tenant.org.id);
  await deleteOrganization(tenant.actors.owner, {
    orgId: tenant.org.id,
    confirmSlug: tenant.org.slug,
  });
  return tenant;
}

/** Rewrites the deletion stamp so the workspace was deleted `ageMs` ago. */
function backdateDeletion(orgId: OrgId, ageMs: number, now: Date = new Date()): void {
  getDb()
    .update(organizations)
    .set({ archivedAt: toIsoTimestamp(new Date(now.getTime() - ageMs)) })
    .where(eq(organizations.id, orgId))
    .run();
}

function countRows(table: typeof members | typeof projects | typeof activityEvents | typeof subscriptions | typeof notifications | typeof invitations, orgId: OrgId): number {
  return getDb().select().from(table).where(eq(table.orgId, orgId)).all().length;
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
  resetOverdueTracking();
});

afterAll(() => {
  cleanup();
});

describe("deleting a workspace", () => {
  it("publishes organization.deleted and audits it", async () => {
    const tenant = await createTenant(`lifecycle-${++counter}`);
    const seen = capture("organization.deleted");

    const deleted = await deleteOrganization(tenant.actors.owner, {
      orgId: tenant.org.id,
      confirmSlug: tenant.org.slug,
    });

    expect(deleted.archivedAt).not.toBeNull();
    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({
      orgId: tenant.org.id,
      actorId: tenant.userIds.owner,
      slug: tenant.org.slug,
    });

    const audit = await activityRepo.listActivityForSubject(
      tenant.org.id,
      "organization",
      tenant.org.id,
    );
    expect(audit.map((row) => row.action)).toEqual(["organization.deleted"]);
    expect(audit[0]?.actorId).toBe(tenant.userIds.owner);
  });

