    const token = "lifecycle-token-" + counter;
    const invitation = await invitationRepo.insertInvitation(
      tenant.org.id,
      { orgId: tenant.org.id, email: "new@x.test", role: "member", expiresInDays: 14 },
      tenant.userIds.owner,
      hashToken(token),
    );
    const outsider = await userRepo.insertUser({
      email: `outsider-${counter}@x.test`,
      name: "Outsider",
      passwordHash: "seed",
    });
    await deleteOrganization(tenant.actors.owner, {
      orgId: tenant.org.id,
      confirmSlug: tenant.org.slug,
    });

    await expect(
      notify(tenant.org.id, "issue_assigned", [tenant.userIds.admin], {
        title: "t",
        body: "b",
        href: "/",
        actorId: null,
      }),
    ).resolves.toEqual([]);
    expect(countRows(notifications, tenant.org.id)).toBe(0);

    await expect(acceptInvitation(outsider.id, { token })).rejects.toBeInstanceOf(NotFoundError);
    const pending = await invitationRepo.listPendingInvitations(tenant.org.id);
    expect(pending.map((row) => row.id)).toEqual([invitation.id]);

    await restoreOrganization(tenant.userIds.owner, tenant.org.id);
    const member = await acceptInvitation(outsider.id, { token });
    expect(member.orgId).toBe(tenant.org.id);
  });

