    );
    const usageBefore = await usageRepo.recomputeUsage(tenant.org.id);
    const delivery = await webhookRepo.enqueueDelivery(tenant.org.id, "endpoint", "issue.created", "{}");
    await deleteOrganization(tenant.actors.owner, {
      orgId: tenant.org.id,
      confirmSlug: tenant.org.slug,
    });

    const overdue = capture("issue.overdue");
    const now = new Date();
    await runOverdueIssueJob(now);
    await runUsageRollupJob(now);
    await runWebhookDeliveryJob(now);
    await runCleanupArchivedJob(now);

    expect(overdue.filter((event) => event.orgId === tenant.org.id)).toEqual([]);
    await expect(usageRepo.listOrgIdsForRollup(1_000)).resolves.not.toContain(tenant.org.id);
    await expect(usageRepo.peekUsage(tenant.org.id)).resolves.toEqual(usageBefore);
    expect(
      getDb().select().from(webhookDeliveries).where(eq(webhookDeliveries.id, delivery.id)).get()?.status,
    ).toBe("failed");
    await expect(orgRepo.findOrgById(tenant.org.id)).resolves.not.toBeNull();

    await restoreOrganization(tenant.userIds.owner, tenant.org.id);
    await runOverdueIssueJob(now);
    expect(overdue.filter((event) => event.orgId === tenant.org.id)).toHaveLength(1);
  });
});

describe("restoring a workspace", () => {
  it("brings it back, publishes organization.restored and audits it", async () => {
    const tenant = await deletedTenant();
