    backdateDeletion(tenant.org.id, WINDOW_MS - 60_000, now);

    await runCleanupArchivedJob(now);

    await expect(orgRepo.findOrgById(tenant.org.id)).resolves.not.toBeNull();
    expect(countRows(members, tenant.org.id)).toBe(4);
    expect(countRows(activityEvents, tenant.org.id)).toBe(1);
  });

